/** Find novena by slug */
export function getNovenaBySlug(slug) {
  return NOVENAS.find((n) => n.slug === slug) || null;
}

/** Get novenas matching at least one intention tag */
export function getNovenasByTag(tag) {
  return NOVENAS.filter((n) => n.intentionTags.includes(tag));
}

/** All unique intention tags */
export const ALL_INTENTION_TAGS = [
  "Healing", "Peace", "Conversion", "Employment", "Family Unity",
  "Courage", "Forgiveness", "Vocations", "Hopeless Causes", "Gratitude",
];
